//go:embed index.html
var page []byte

//go:embed collect.py
var collector string

//go:embed login.html
var loginSource string

//go:embed ui.css
var stylesheet []byte

//go:embed mark.svg
var mark []byte

// Logo assets are generated by scripts/make_logo.py and committed. They are public
// because the login page needs them before a session exists.
//
//go:embed logo.png
var logoPNG []byte

//go:embed logo-64.png
var logo64PNG []byte

//go:embed favicon-32.png
var favicon32PNG []byte

//go:embed favicon.ico
var faviconICO []byte

// publicAssets are the only unauthenticated responses besides /login.
var publicAssets = map[string]struct {
	kind string
	body *[]byte
}{
	"/favicon.svg":    {"image/svg+xml", &mark},
	"/logo.png":       {"image/png", &logoPNG},
	"/logo-64.png":    {"image/png", &logo64PNG},
	"/favicon-32.png": {"image/png", &favicon32PNG},
	"/favicon.ico":    {"image/x-icon", &faviconICO},
}

var loginPage = template.Must(template.New("login").Parse(loginSource))

type object = map[string]any

type server struct {
	mu             sync.RWMutex
	data           object
	failure        string
	profile, state string
	since          int64
	redis          *redis.Client
	dedup          string
	auth           *auth      // nil = locked: no data is served
	zones          []string   // recently requested non-UTC zones, least recent first
	zoneMu         sync.Mutex // serializes first-use day-bucket computations
	briefs         briefCache
	runBrief       func(ctx context.Context, profile, state string, hours, n int, tz string, since int64) (object, error) // nil = runBrief; tests stub it
	slow           object                                                                                                 // last good slow panels (see slowKeys); merged into every fast snapshot
	slowAt         time.Time                                                                                              // when slow was collected; zero = never
	slowFailure    string
	runCollector   func(ctx context.Context, mode string, zones []string) ([]byte, error) // nil = python3; tests stub it
}

var identifier = regexp.MustCompile(`^[A-Za-z0-9_.:-]{1,150}$`)

// collectDeadline bounds one collector run. 20s left the dashboard without data on a cold page
// cache and under heavy host load (runs were killed repeatedly); time.Tick drops
// ticks while a run is slow, so a longer deadline never overlaps runs, it only stretches the period.
const collectDeadline = 60 * time.Second

// Refresh cadence. The fast panels (event journal, latest NAV row, services, Hermes) refresh every
// refreshPeriod. The slow panels are day-scale or 48h-scale evidence (day calendars per viewer zone,
// the 14-day NAV bridge, the rent journal, Robinhood unit journals) and were ~80% of a refresh's
// CPU, mostly journalctl --grep and NAV lookups in a ~200MB file; they refresh every slowPeriod.
const (
	refreshPeriod = 60 * time.Second
	slowPeriod    = 10 * time.Minute
)

// slowKeys must match SLOW_KEYS in collect.py.
var slowKeys = []string{"by_tz", "nav_bridge", "live", "robinhood", "experiments"}

// collectorCommand runs the embedded collector with args. The source goes in on stdin (`python3 -`), never
// as `python3 -c <source>`: Linux caps one argv string at 128 KiB (MAX_ARG_STRLEN) and collect.py outgrew it,
// which fails every run with "argument list too long". sys.argv indexes are the same either way.
func collectorCommand(ctx context.Context, args ...string) *exec.Cmd {
	cmd := exec.CommandContext(ctx, "python3", append([]string{"-"}, args...)...)
	cmd.Stdin = strings.NewReader(collector)
	return cmd
}

// collect runs one collector mode ("fast", "slow" or "daily") and decodes its snapshot.
func (s *server) collect(ctx context.Context, mode string, zones []string) (object, error) {
	run := s.runCollector
	if run == nil {
		run = func(ctx context.Context, mode string, zones []string) ([]byte, error) {
			return collectorCommand(ctx, s.profile, s.state, strconv.FormatInt(s.since, 10), strings.Join(zones, ","), mode).Output()
		}
	}
	output, err := run(ctx, mode, zones)
	var data object
	if err == nil {
		err = json.Unmarshal(output, &data)
	}
	if err != nil {
		// The last stderr line names the failing step; the collector masks credentials it reads.
		detail := ""
		if exit, ok := err.(*exec.ExitError); ok {
			lines := strings.Split(strings.TrimSpace(string(exit.Stderr)), "\n")
			if detail = lines[len(lines)-1]; len(detail) > 300 {
				detail = detail[:300]
			}
		}
		log.Printf("collector (%s) failed: %v %s", mode, err, detail)
		return nil, err
	}
	return data, nil
}

// refresh collects the fast panels, and the slow panels too when they are due, then publishes
// fast + last good slow as one snapshot. Runs are sequential, never concurrent.
func (s *server) refresh() {
	s.mu.RLock()
	due := s.slow == nil || time.Since(s.slowAt) >= slowPeriod
	s.mu.RUnlock()
	if due {
		ctx, cancel := context.WithTimeout(context.Background(), collectDeadline)
		slow, err := s.collect(ctx, "slow", s.zoneList())
		cancel()
		s.mu.Lock()
		if err == nil {
			s.slow, s.slowAt, s.slowFailure = slow, time.Now(), ""
		} else {
			// Retry on the next fast tick rather than waiting a whole slow period.
			s.slowFailure = "Slow panel collection failed; last successful slow panels retained"
		}
		s.mu.Unlock()
	}
	ctx, cancel := context.WithTimeout(context.Background(), collectDeadline)
	defer cancel()
	data, err := s.collect(ctx, "fast", nil)
	if err != nil {
		s.mu.Lock()
		s.failure = "Local collection failed; last successful snapshot retained"
		s.mu.Unlock()
		return
	}
	data["redis"] = s.redisSnapshot(ctx, data)
	s.mu.Lock()
	for _, k := range slowKeys {
		if v, ok := s.slow[k]; ok {
			data[k] = v
		}
	}
	if s.slow != nil {
		data["slow_collected_at"] = s.slow["collected_at"]
	}
	s.data = data
	s.failure = s.slowFailure
	s.mu.Unlock()
}

func (s *server) redisSnapshot(ctx context.Context, data object) object {
	if s.redis == nil {
		return object{"status": "disabled", "observed_at": time.Now().Unix()}
	}
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()
	keys := map[string]bool{"sol:dlmm:capacity:wallet": true, "sol:dlmm:capacity:pulse": true, "sol:dlmm:capacity:turnover": true}
	// ponytail: bounded recent candidates; use an indexed collector for historical Redis coverage.
	rows, _ := data["journal"].([]any)
	for i, row := range rows {
		if i >= 100 {
			break
		}
		r, _ := row.(map[string]any)
		e, _ := r["evidence"].(map[string]any)
		for _, k := range []string{"pool", "base_mint", "base_symbol"} {
			v, _ := e[k].(string)
			if c, ok := e["candidate"].(map[string]any); ok && v == "" {
				v, _ = c[k].(string)
			}
			if !identifier.MatchString(v) {
				continue
			}
			switch k {
			case "pool":
				keys["sol:dlmm:cooldown:pool:"+v] = true
				for _, mode := range []string{"pulse", "turnover"} {
					keys[s.dedup+":"+mode+":"+v] = true
				}
			case "base_mint":
				keys["sol:dlmm:cooldown:mint:"+v] = true
			case "base_symbol":
				keys["sol:dlmm:cooldown:"+strings.ToUpper(v)] = true
			}
		}
	}
	count, err := s.redis.SCard(ctx, "sol:dlmm:active_positions").Result()
	if err != nil {
		return object{"status": "unavailable", "observed_at": time.Now().Unix()}
	}
	positions, _, err := s.redis.SScan(ctx, "sol:dlmm:active_positions", 0, "", 100).Result()
	if err != nil {
		return object{"status": "unavailable", "observed_at": time.Now().Unix()}
	}
	if len(positions) > 100 {
		positions = positions[:100]
	}
	for _, p := range positions {
		if identifier.MatchString(p) {
			keys["sol:dlmm:position:"+p] = true
		}
	}
	names := make([]string, 0, len(keys))
	for k := range keys {
		names = append(names, k)
	}
	sort.Strings(names)
	if len(names) > 400 {
		names = names[:400]
	}
	pipe := s.redis.Pipeline()
	ttls := make(map[string]*redis.DurationCmd)
	values := make(map[string]*redis.StringCmd)
	for _, k := range names {
		ttls[k] = pipe.TTL(ctx, k)
		values[k] = pipe.GetRange(ctx, k, 0, 8191)
	}
	_, err = pipe.Exec(ctx)
	result := make([]object, 0, len(names))
	for _, k := range names {
		row := object{"key": k, "ttl_seconds": nil, "value": nil}
		if ttl, e := ttls[k].Result(); e == nil {
			if ttl < 0 {
				row["ttl_seconds"] = int64(ttl)
			} else {
				row["ttl_seconds"] = ttl.Seconds()
			}
		}
		if raw, e := values[k].Result(); e == nil && raw != "" {
			if strings.HasPrefix(k, "sol:dlmm:position:") {
				var p object
				if json.Unmarshal([]byte(raw), &p) == nil {
					safe := object{}
					for _, f := range []string{"position", "pool", "mode", "base_mint", "base_symbol", "deposit_sol", "size_sol", "strategy", "deployed_at", "tx_hash", "orphan", "created_at", "updated_at", "root_chain_id", "entry_id"} {
						safe[f] = p[f]
					}
					row["value"] = safe
				}
			}
			// Capacity/cooldown/dedup values can contain arbitrary upstream errors; TTL suffices.
		}
		result = append(result, row)
	}
	status := "ok"
	if err != nil {
		status = "partial"
	}
	return object{"status": status, "observed_at": time.Now().Unix(), "active_position_count": count, "position_sample_count": len(positions), "rows": result, "scope": "Fixed capacity keys, one bounded active-position SSCAN, recent-candidate cooldown/dedup TTLs; missing key=-2, no expiry=-1. Not a full inventory."}
}

func (s *server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	host, _, err := net.SplitHostPort(r.Host)
	if err != nil {
		host = r.Host
	}
	if host != "localhost" && net.ParseIP(host) != nil && !net.ParseIP(host).IsLoopback() || host != "localhost" && net.ParseIP(host) == nil {
		http.Error(w, "localhost only", http.StatusForbidden)
		return
	}
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("Content-Security-Policy", "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'")
	// same-origin, not no-referrer: no-referrer makes browsers send "Origin: null" on the login POST.
	w.Header().Set("Referrer-Policy", "same-origin")
	switch r.URL.Path {
	case "/login":
		s.serveLogin(w, r)
		return
	case "/logout":
		s.serveLogout(w, r)
		return
	}
	if r.Method != "GET" && r.Method != "HEAD" {
		w.Header().Set("Allow", "GET, HEAD")
		http.Error(w, "read only", 405)
		return
	}
	// The login page's own assets are the only unauthenticated responses.
	if a, ok := publicAssets[r.URL.Path]; ok {
		w.Header().Set("Content-Type", a.kind)
		w.Header().Set("Cache-Control", "public, max-age=3600")
		w.Write(*a.body)
		return
	}
	switch r.URL.Path {
	case "/ui.css":
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		w.Write(stylesheet)
		return
	}
	if !s.signedIn(r) {
		if strings.HasPrefix(r.URL.Path, "/api/") {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusUnauthorized)
			w.Write([]byte(`{"error":"login required"}` + "\n"))
			return
		}
		http.Redirect(w, r, "/login", http.StatusSeeOther)
		return
	}
	if r.URL.Path == "/" {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.Write(page)
		return
	}
	if r.URL.Path == "/api/agent/brief" {
		s.serveBrief(w, r)
		return
	}
	s.mu.RLock()
	data := s.data
	failure := s.failure
	s.mu.RUnlock()
	if data == nil {
		http.Error(w, "Waiting for first local snapshot", 503)
		return
	}
	var value any
	switch r.URL.Path {
	case "/api/overview":
		value = object{"collected_at": data["collected_at"], "collection_error": failure, "nav": data["nav"], "services": data["services"], "sources": data["sources"]}
	case "/api/capital", "/api/live", "/api/robinhood", "/api/growth":
		lines, ok := logLines(r.URL.Query().Get("n"))
		if !ok {
			http.Error(w, "invalid n: use 1 to 1000", 400)
			return
		}
		tz, fallback := requestZone(r.URL.Query().Get("tz"))
		panels, problem := s.daily(data, tz)
		if panels == nil && tz != "UTC" {
			tz, fallback = "UTC", true
			panels, _ = s.daily(data, tz)
		}
		zoneInfo := object{"tz": tz, "tz_fallback": fallback, "tz_error": problem}
		if r.URL.Path == "/api/capital" {
			value = object{"north_star": panels["north_star"], "nav_bridge": data["nav_bridge"]}
		} else if r.URL.Path == "/api/growth" {
			value = object{"collected_at": data["collected_at"], "north_star": panels["north_star"], "growth": panels["growth"], "experiments": data["experiments"]}
		} else if r.URL.Path == "/api/robinhood" {
			value = robinhoodView(data, panels, lines)
		} else {
			live := object{"realized": panels["realized"]}
			if old, ok := data["live"].(map[string]any); ok {
				for k, v := range old {
					live[k] = v
				}
			}
			value = object{"live": live}
		}
		for k, v := range zoneInfo {
			value.(object)[k] = v
		}
	case "/api/hermes":
		value = data["hermes"]
	case "/api/redis":
		value = data["redis"]
	case "/api/journal":
		offset, err := strconv.Atoi(r.URL.Query().Get("offset"))
		if r.URL.Query().Get("offset") == "" {
			offset = 0
			err = nil
		}
		if err != nil || offset < 0 || offset > 100000 {
			http.Error(w, "invalid offset", 400)
			return
		}
		query := strings.ToLower(r.URL.Query().Get("q"))
		stage := r.URL.Query().Get("stage")
		if len(query) > 200 {
			http.Error(w, "query too long", 400)
			return
		}
		matched := []any{}
		rows, _ := data["journal"].([]any)
		for _, row := range rows {
			e, _ := row.(map[string]any)
			b, _ := json.Marshal(e)
			if (stage == "" || e["stage"] == stage) && (query == "" || strings.Contains(strings.ToLower(string(b)), query)) {
				matched = append(matched, row)
			}
		}
		total := len(matched)
		if offset > total {
			offset = total
		}
		end := offset + 50
		if end > total {
			end = total
		}
		value = object{"rows": matched[offset:end], "total_in_retained_tail": total, "offset": offset, "limit": 50, "collected_at": data["collected_at"], "scope": "Bounded source tails; correlations require shared delivery_id, entry_id, root_chain_id, position or signature. Pool/time similarity is not execution proof."}
	default:
		http.NotFound(w, r)
		return
	}
	// Copy the envelope: never mutate the cached snapshot while serving a reader.
	if payload, ok := value.(map[string]any); ok {
		withStatus := make(object, len(payload)+2)
		for key, item := range payload {
			withStatus[key] = item
		}
		withStatus["collected_at"] = data["collected_at"]
		withStatus["collection_error"] = failure
		value = withStatus
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(value)
}

// Only these Redis settings are read; trading/model configuration is never loaded.
func redisSettings(path string) map[string]string {
	values := map[string]string{}
	f, err := os.Open(path)
	if err == nil {
		defer f.Close()
		scan := bufio.NewScanner(f)
		for scan.Scan() {
			line := strings.TrimSpace(strings.TrimPrefix(scan.Text(), "export "))
			key, value, ok := strings.Cut(line, "=")
			key = strings.TrimSpace(key)
			if ok && (key == "REDIS_ADDR" || key == "REDISCLI_AUTH" || key == "REDIS_SEEN_KEY") {
				values[key] = strings.Trim(strings.TrimSpace(value), "\"'")
			}
		}
	}
	for _, key := range []string{"REDIS_ADDR", "REDISCLI_AUTH", "REDIS_SEEN_KEY"} {
		if value, ok := os.LookupEnv(key); ok {
			values[key] = value
		}
	}
	return values
}

func main() {
	if len(os.Args) > 1 && os.Args[1] == "brief" {
		os.Exit(briefMain(os.Args[2:], os.Stdout, os.Stderr))
	}
	if len(os.Args) > 1 && os.Args[1] == "alerts" {
		os.Exit(alertsMain(os.Args[2:], os.Stdout, os.Stderr))
	}
	if len(os.Args) > 1 && os.Args[1] == "trace" {
		os.Exit(traceMain(os.Args[2:], os.Stdout, os.Stderr))
	}
	home, _ := os.UserHomeDir()
	addr := flag.String("listen", "127.0.0.1:8787", "loopback address")
	profile := flag.String("profile", filepath.Join(home, ".hermes/profiles/dlmm"), "Hermes profile directory")
	state := flag.String("state", filepath.Join(home, ".local/state/azimuth"), "persisted state directory")
	redisAddr := flag.String("redis", "", "Redis address override; use disabled to disable")
	envFile := flag.String("env-file", ".env", "read only REDIS_ADDR, REDISCLI_AUTH and REDIS_SEEN_KEY")
	dedup := flag.String("dedup-prefix", "", "scanner REDIS_SEEN_KEY override")
	since := flag.Int64("since", 0, "live-change cutover as unix seconds; 0 = the last 7 days")
	hashMode := flag.Bool("hash-password", false, "read a password from the first stdin line, print its DASHBOARD_PASSWORD_HASH value and exit")
	flag.Parse()
	if *hashMode {
		password, err := readPassword(os.Stdin)
		if err == nil {
			var hash string
			if hash, err = hashPassword(password, hashIterations); err == nil {
				fmt.Println(hash)
				return
			}
		}
		log.Fatal("hash-password: ", err)
	}
	// A missing profile would serve an empty dashboard that looks healthy; stop instead.
	if info, err := os.Stat(*profile); err != nil || !info.IsDir() {
		log.Fatalf("profile directory %s not found; pass -profile <dir>", *profile)
	}
	host, _, err := net.SplitHostPort(*addr)
	if err != nil || net.ParseIP(host) == nil || !net.ParseIP(host).IsLoopback() {
		log.Fatal("listen must use a loopback IP")
	}
	settings := redisSettings(*envFile)
	if *redisAddr == "" {
		*redisAddr = settings["REDIS_ADDR"]
	}
	if *dedup == "" {
		*dedup = settings["REDIS_SEEN_KEY"]
	}
	if *dedup == "" {
		*dedup = "dlmm:signal:seen_pools"
	}
	if *since < 0 {
		log.Fatal("since must be unix seconds or 0")
	}
	hashValue, hashSet := os.LookupEnv("DASHBOARD_PASSWORD_HASH")
	s := &server{profile: *profile, state: *state, dedup: *dedup, since: *since, auth: newAuth(hashValue, hashSet)}
	if s.auth.problem != "" {
		log.Print("dashboard locked: ", s.auth.problem)
	}
	if *redisAddr != "" && *redisAddr != "disabled" {
		s.redis = redis.NewClient(&redis.Options{Addr: *redisAddr, Password: settings["REDISCLI_AUTH"], MaxRetries: -1, DialTimeout: time.Second, ReadTimeout: time.Second})
		defer s.redis.Close()
	}
	s.refresh()
	go func() {
		for range time.Tick(refreshPeriod) {
			s.refresh()
		}
	}()
	fmt.Printf("Azimuth dashboard: http://%s (read only)\n", *addr)
	log.Fatal((&http.Server{Addr: *addr, Handler: s, ReadHeaderTimeout: 5 * time.Second, WriteTimeout: 10 * time.Second, IdleTimeout: 60 * time.Second}).ListenAndServe())
}
